update public.mecha_kaijus_catalogo set vida=case when vida>0 then vida else 180 end,agilidade=case when agilidade>0 then agilidade else 7 end,defesa=case when defesa<>0 then defesa else 0 end,codex_texto='Ao acertar o nome e o efeito de todas as habilidades deste Kaiju, você recebe um ataque dele de Ás a 10.',ataques='{"2":{"nome":"Sufocamento","dano":7,"descricao":"Atinge o jogador à esquerda."},"3":{"nome":"Presa caótica","dano":7,"descricao":"Atinge um alvo aleatório."},"4":{"nome":"Bate nas extremidades","dano":5,"descricao":"Bate nas extremidades."},"5":{"nome":"Giro rasteiro","dano":3,"descricao":"Quem sofre o dano troca de lugar."},"6":{"nome":"Cuspida tóxica","dano":5,"descricao":"Acerta o jogador mais ao meio."},"7":{"nome":"Espreita ilusória","dano":7,"descricao":"Acerta um alvo aleatório."},"8":{"nome":"Bote surpresa","dano":5,"descricao":"Ataca o jogador do meio."},"9":{"nome":"Bote cego","dano":5,"descricao":"Acerta um jogador aleatório."},"10":{"nome":"Cauda chicote tempestuoso","dano":3,"descricao":"Causa 3 de dano em todos os jogadores."},"A":{"nome":"Bote preciso","dano":7,"descricao":"Atinge o jogador à direita."},"J":{"nome":"Jogo da memória","dano":5,"descricao":"Memorize: Escama, veneno, bote, asas, chocalho, sombras. Se errar, recebe 5 de dano."},"Q":{"nome":"Abrir asas","dano":5,"descricao":"Todo golpe tem 50% de chance de erro."},"K":{"nome":"Serpente enfeitiçou","dano":7,"descricao":"Enfeitiça o jogador e causa 7 de dano."}}'::jsonb where id='cobra-falante' and ataques='{}'::jsonb and not personalizado;
