update public.mecha_kaijus_catalogo set vida=case when vida>0 then vida else 340 end,agilidade=case when agilidade>0 then agilidade else 6 end,defesa=case when defesa<>0 then defesa else 2 end,codex_texto='Uma criatura colossal que combina a resistência de uma tartaruga com o poder destrutivo de um dragão.',ataques='{"2":{"nome":"Casco esmagador","dano":12,"descricao":"Causa 12 de dano no jogador com mais vida."},"3":{"nome":"Tremor de terra","dano":1,"descricao":"Causa 1 de dano em todos os jogadores."},"4":{"nome":"Punição do casco","dano":4,"descricao":"Causa 4 de dano; a equipe escolhe quem recebe."},"5":{"nome":"Mordida quebra-ossos","dano":4,"descricao":"Causa 4 de dano; se o alvo atacou o Kaiju, causa 8."},"6":{"nome":"Âncora de dano","dano":7,"descricao":"Causa 7 de dano; a equipe escolhe quem recebe."},"7":{"nome":"Repulsa brutal","dano":5,"descricao":"Causa 5 de dano; a equipe escolhe quem recebe."},"8":{"nome":"Muralha de espinhos","dano":5,"descricao":"Devolve 3 de dano."},"9":{"nome":"Gêiser subterrâneo","dano":6,"descricao":"Causa 6 de dano em um jogador aleatório."},"10":{"nome":"Peso do milênio","dano":1,"descricao":"O dano é dobrado."},"A":{"nome":"Esmagar defesa","dano":9,"descricao":"Causa 9 de dano no alvo escolhido pela equipe."},"J":{"nome":"Instância mutável","dano":2,"descricao":"2 de dano e 5 de defesa, ou 2 de dano e -2."},"Q":{"nome":"Distorção temporal","dano":0,"descricao":"Um jogador fica em estátua, inquieto, agitado e lento. O efeito acaba quando o Kaiju sofre 80 de dano."},"K":{"nome":"Palácio do equilíbrio","dano":4,"descricao":"Se a torre de cartas cair, o Kaiju fica imune, recebe 20 cartas e toma 4 de dano."}}'::jsonb where id='tartaruga-dragao' and ataques='{}'::jsonb and not personalizado;

